import java.util.Deque;
import java.util.ArrayDeque;

public class ValidateBinarySearchTree {

    // ===== 方法 1：递归传区间（面试首选） =====
    public boolean isValidBST(TreeNode root) {
        return helper(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean helper(TreeNode node, long low, long high) {
        if (node == null) return true;                   // 空树是 BST
        if (node.val <= low || node.val >= high) return false; // 越界
        return helper(node.left, low, node.val)          // 左子树：上界收紧
            && helper(node.right, node.val, high);       // 右子树：下界收紧
    }

    // ===== 方法 2：中序遍历 =====
    public boolean isValidBSTInorder(TreeNode root) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode curr = root;
        long prev = Long.MIN_VALUE;                       // 前一个节点值

        while (curr != null || !stack.isEmpty()) {
            while (curr != null) {                        // 一路向左
                stack.push(curr);
                curr = curr.left;
            }
            curr = stack.pop();                           // 弹出即中序访问
            if (curr.val <= prev) return false;           // 不严格递增
            prev = curr.val;
            curr = curr.right;                            // 转向右子树
        }
        return true;
    }

    // ===== 测试 =====
    public static void main(String[] args) {
        ValidateBinarySearchTree s = new ValidateBinarySearchTree();

        // case 1: 合法 BST
        TreeNode root1 = new TreeNode(2, new TreeNode(1), new TreeNode(3));
        System.out.println(s.isValidBST(root1));          // true
        System.out.println(s.isValidBSTInorder(root1));   // true

        // case 2: 跨层违规 [5,1,4,null,null,3,6]
        TreeNode root2 = new TreeNode(5,
            new TreeNode(1),
            new TreeNode(4, new TreeNode(3), new TreeNode(6)));
        System.out.println(s.isValidBST(root2));          // false
        System.out.println(s.isValidBSTInorder(root2));   // false

        // case 3: 节点值等于 Integer.MIN_VALUE
        TreeNode root3 = new TreeNode(Integer.MIN_VALUE);
        System.out.println(s.isValidBST(root3));          // true（用 long 避免溢出）
    }
}

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val; this.left = left; this.right = right;
    }
}
